// Bounded ReAct loop with trail logging (plain JS pattern)
function reactLoop(plan, act, observe, isDone, budget = { iters: 8 }) {
  const trail = [];
  let state = {};
  for (let i = 0; i < budget.iters; i++) {
    const step = plan(state);
    const result = act(step);
    state = observe(state, result);
    trail.push({ i, step: step.kind, note: result.note });
    if (isDone(state)) return { ok: true, state, trail };
  }
  return { ok: false, reason: "budget-exhausted", state, trail };
}
// Trail logs every iteration: stuck patterns visible post-hoc, not inferred.

// Progress watch: identical observations trip stuck escalation (plain JS)
function progressWatch(maxRepeat = 3) {
  let last = null, repeats = 0;
  return (observation) => {
    const key = JSON.stringify(observation);
    repeats = key === last ? repeats + 1 : 0;
    last = key;
    return repeats >= maxRepeat ? { stuck: true } : { stuck: false };
  };
}
// Stuck escalates with trail; slow continues with evidence of motion.

